@__export('con_uw_master_4')
def withdrawal():
    sender = ctx.caller
    assert __balances[sender, 'rewards'] > 0, 'Cannot send negative balances!'
    if __metadata['withdrawal'] == True:
        if (now - __balances[sender, 'rewards', 'time']).days > __metadata[
            'time']:
            amount = __balances[sender, 'rewards']
            con_uwarriors_lst001.transfer_from(amount, sender, __metadata[
                'operator'])
            __balances[sender, 'rewards'] = 0
            __balances[uid, 'rewards', 'time'] = now
        else:
            con_uwarriors_lst001.transfer_from(amount - amount * __metadata
                ['fees_withdrawal'], sender, __metadata['operator'])
            __balances[sender, 'rewards'] = 0
            __balances[uid, 'rewards', 'time'] = now


